console.log("deepseek api client");
function createClient(config) {
    if (!config.apiKey) {
        throw new Error('API key is required to create a DeepSeek client.');
    }

    return {
        generateText: async ({ model, prompt, maxTokens }) => {
            // Simulate a response from the API
            return {
                text: `Generated text for prompt: ${prompt}`,
            };
        },
    };
}

module.exports = { createClient };
